import sys
sys.path.insert(0,'/tmp')
from getmap import get,parse

def mirrored_value(arr,W,H,tw,th,x,y):
    # tile index
    tx=x//tw; ty=y//th
    lx=x%tw; ly=y%th
    if tx%2==1: lx=tw-1-lx
    if ty%2==1: ly=th-1-ly
    return arr[ly*W+lx]

def check_mirror(arr,W,H,tw,th):
    for y in range(H):
        for x in range(W):
            if arr[y*W+x]!=mirrored_value(arr,W,H,tw,th,x,y): return False
    return True

def check_periodic(arr,W,H,tw,th):
    for y in range(H):
        for x in range(W):
            if arr[y*W+x]!=arr[(y%th)*W+(x%tw)]: return False
    return True

def analyze(w,h,seed,nb):
    r,caps=get(w,h,seed,nb,None)
    pid,wh,prod,owners,stren=parse(caps[0]); W,H=wh
    sols=[]
    for tw in range(1,W+1):
        if W%tw!=0: continue
        for th in range(1,H+1):
            if H%th!=0: continue
            if check_mirror(prod,W,H,tw,th) and check_mirror(stren,W,H,tw,th):
                sols.append((tw,th,'mirror'))
            elif check_periodic(prod,W,H,tw,th) and check_periodic(stren,W,H,tw,th):
                sols.append((tw,th,'period'))
    print(f"req{w}x{h} p{nb} seed{seed} actual{W}x{H} owners{[(i%W,i//W,o) for i,o in enumerate(owners) if o]} sols={sols[:20]}")
for nb in [1,2,3,4,5,6]:
    for seed in [0,1,42]:
        analyze(20,20,seed,nb)
for nb in [1,2,3,4,5,6]:
    analyze(30,30,42,nb)
    analyze(24,24,42,nb)
    analyze(40,40,42,nb)
PY
