import sys
sys.path.insert(0,'/tmp')
from getmap import get,parse

def symmetries(w,h,seed,nb):
    r,caps=get(w,h,seed,nb,None)
    pid,wh,prod,owners,stren=parse(caps[0]); W,H=wh
    arr=[(prod[i],stren[i]) for i in range(W*H)]
    sols=[]
    # transforms on coordinates: (x,y) -> (sx * X + a, sy * Y + b) where (X,Y) either (x,y) if dims allow or (y,x)
    modes=[]
    modes.append(('id',lambda x,y:(x,y)))
    if W==H:
        modes.append(('swap',lambda x,y:(y,x)))
    for name,f in modes:
        for sx in [1,-1]:
            for sy in [1,-1]:
                # find a,b candidate by mapping (0,0) to each cell with same value? Brute all a,b but W*H * checks early break maybe okay for 20x20 and candidates 400*8*400=1.28M
                for a in range(W):
                    for b in range(H):
                        ok=True
                        for y in range(H):
                            for x in range(W):
                                X,Y=f(x,y)
                                nx=(sx*X+a)%W; ny=(sy*Y+b)%H
