import subprocess, sys
sys.path.insert(0,'/tmp')
from getmap2 import get,parse
def raws(seed,n=500):
    return list(map(int,subprocess.check_output(['/tmp/mtseq',str(seed),str(n)]).split()))
def pcand(r): return 6+r%10
def scand(r): return 150+r%106
for (w,h,seed) in [(1,1,1),(2,2,1),(1,2,1),(1,3,1),(3,3,1),(4,4,1),(1,1,42),(2,2,42),(5,5,42),(10,10,42)]:
