def getA(j,start,useodd=False,combine=False):
    A=[]
    for i in range(9):
        r1=raws[j][start+2*i]; r2=raws[j][start+2*i+1]
        if combine: A.append(((r1<<32)|r2)/18446744073709551616)
        elif useodd: A.append(r2/4294967296)
        else: A.append(r1/4294967296)
    return A

def smooth(A,w0,w1,w2):
    B=[]
    for y in range(3):
        for x in range(3):
            val=w0*A[y*3+x]
            for dy in [-1,0,1]:
                for dx in [-1,0,1]:
                    if dx==0 and dy==0: continue
                    xx=(x+dx)%3; yy=(y+dy)%3
                    wt=w1 if dx==0 or dy==0 else w2
                    val+=wt*A[yy*3+xx]
            B.append(val)
    return B

