        while True:
            line=sys.stdin.readline()
            if not line: break
            self.owners,self.strengths=self.parse(line)
            moves=func(self) or []
            # moves can be list of (x,y,d) or raw string
            if isinstance(moves,str): out=moves
            else: out=" ".join(f"{x} {y} {d}" for x,y,d in moves)
            sys.stdout.write(out+"\n");sys.stdout.flush();self.turn+=1
    def owned(self):
        return [(x,y) for y in range(self.H) for x in range(self.W) if self.owners[y*self.W+x]==self.pid]
    def at(self,x,y): return self.owners[(y%self.H)*self.W+(x%self.W)],self.strengths[(y%self.H)*self.W+(x%self.W)]
