import sys
class Bot:
    def __init__(self,name="Bot"):
        self.pid=int(sys.stdin.readline())
        self.W,self.H=map(int,sys.stdin.readline().split())
        self.prod=list(map(int,sys.stdin.readline().split()))
        self.owners,self.strengths=self.parse(sys.stdin.readline())
        sys.stdout.write(name+"\n");sys.stdout.flush();self.turn=0
    def parse(self,line):
        m=list(map(int,line.split()));idx=0;owners=[]
        while len(owners)<self.W*self.H:
            c,o=m[idx],m[idx+1];idx+=2;owners.extend([o]*c)
        return owners,m[idx:]
    def run(self,func):
        while True:
            line=sys.stdin.readline()
            if not line: break
            self.owners,self.strengths=self.parse(line)
            moves=func(self) or []
            # moves can be list of (x,y,d) or raw string
            if isinstance(moves,str): out=moves
            else: out=" ".join(f"{x} {y} {d}" for x,y,d in moves)
            sys.stdout.write(out+"\n");sys.stdout.flush();self.turn+=1
    def owned(self):
        return [(x,y) for y in range(self.H) for x in range(self.W) if self.owners[y*self.W+x]==self.pid]
    def at(self,x,y): return self.owners[(y%self.H)*self.W+(x%self.W)],self.strengths[(y%self.H)*self.W+(x%self.W)]
