DIRS=[(0,0),(0,-1),(1,0),(0,1),(-1,0)]
def trans(frame,moves,prod,W,H):
    # production
    src=[[list(frame[y][x]) for x in range(W)] for y in range(H)]
    for y in range(H):
        for x in range(W):
            if src[y][x][0]!=0 and moves[y][x]==0:
                src[y][x][1]=min(255,src[y][x][1]+prod[y][x])
    # presence dict per cell, and base site owner/strength for no incoming
    pres=[[dict() for x in range(W)] for y in range(H)]
    # neutral defenders
    for y in range(H):
        for x in range(W):
            if frame[y][x][0]==0 and frame[y][x][1]>0:
                pres[y][x][0]=frame[y][x][1]
    # player movements (including still/invalid to self)
    for y in range(H):
        for x in range(W):
            o,s=src[y][x]
            if o==0: continue
            d=moves[y][x]
            if d in [1,2,3,4]: dx,dy=DIRS[d]; nx,ny=(x+dx)%W,(y+dy)%H
            else: nx,ny=x,y
            pres[ny][nx][o]=min(255,pres[ny][nx].get(o,0)+s)
    out=[]
    for y in range(H):
        row=[]
        for x in range(W):
            pr=pres[y][x]
            # remove zero? Player territory base if original owner player and no player presence (piece moved out/died? presence 0 possible) handled below
            if not pr:
                # original site: if neutral strength0 ->0,0; if player -> player,0
                row.append([frame[y][x][0],0])
            elif set(pr.keys())=={0}:
                row.append([0,pr[0]])
            elif 0 not in pr:
                # single player only in this test; if original was player who moved out and incoming same etc
                # if pr has one player:
                if len(pr)==1:
                    o,s=next(iter(pr.items()));row.append([o,s])
                else:
                    row.append([-1,-1])
            else:
                ns=pr[0]; players={o:s for o,s in pr.items() if o!=0}
                if len(players)==1:
                    o,s=next(iter(players.items()))
                    if s>ns:row.append([o,s-ns])
                    elif s<ns:row.append([0,ns-s])
                    else:row.append([0,0])
                else:row.append([-2,-2])
        out.append(row)
    return out

def test(seed,size):
    for f in glob.glob('*.hlt'):os.remove(f)
    r=subprocess.run(["./executable","-q","-d",f"{size} {size}","-s",str(seed),"python3 /tmp/expand_bot.py"],capture_output=True,text=True,timeout=10)
    d=json.load(open(glob.glob('*.hlt')[0]));W=d['width'];H=d['height'];prod=d['productions']
    mism=0;total=0
    for i in range(len(d['moves'])):
        pred=trans(d['frames'][i],d['moves'][i],prod,W,H); actual=d['frames'][i+1]
        for y in range(H):
            for x in range(W):
                total+=1
                if pred[y][x]!=actual[y][x]:
                    if mism<10:print("mismatch seed",seed,"frame",i,"cell",x,y,"pred",pred[y][x],"actual",actual[y][x],"src",d['frames'][i][y][x],"move",d['moves'][i][y][x],"prod",prod[y][x])
                    mism+=1
    print("seed",seed,size,"mism",mism,"/",total)
for seed in [42,1,2,3]:test(seed,10)
for seed in [42,1]:test(seed,20)
