            if 6+raw[k]%10==max(p) and 150+raw[k+1]%106==max(s):K=k;break
        L=(K-6)//4;sstart=4+2*(L+1)
        data.append((p,s,raw,K,L,sstart))
    return data

def score(data,n,weights,gamma,mode='round'):
    err=0;ex=0;cnt=0
    for p,s,raw,K,L,sstart in data:
        for finals,start,M in [(p,4,max(p)),(s,sstart,max(s))]:
            A=[raw[start+2*i]/4294967296 for i in range(n)];Ap=[x**gamma for x in A];B=[]
            for i in range(n):
                tot=0
                for d,w in weights.items():
                    # sum cells at toroidal distance exactly d (for d=0 itself; for n=2d opposite counted once in our sum via set)
                    cells=set()
                    if d==0:cells={i}
