import pickle,math,sys,subprocess
sys.path.insert(0,'/tmp')
from getfast import get,parse

def get_data(w,h,seeds):
    data=[]
    for seed in seeds:
        r,caps=get(w,h,seed,1);pid,wh,p,o,s=parse(caps[0]);raw=list(map(int,subprocess.check_output(['/tmp/mtseq',str(seed),'1000']).split()))
        K=None
        for k in range(500):
            if 6+raw[k]%10==max(p) and 150+raw[k+1]%106==max(s):K=k;break
        L=(K-6)//4;sstart=4+2*(L+1)
        # only use if leaves are exactly cells and latent mapping row-major for w*h<=16 and max(w,h)<=4
        for finals,start,M in [(p,4,max(p)),(s,sstart,max(s))]:
            A=[raw[start+2*i]/4294967296 for i in range(w*h)];data.append((A,finals,M))
    return data

def smooth(A,w,h,iters,alpha,neigh='4',inplace=True,gamma=1.5):
    B=[x**gamma for x in A]
    dirs4=[(0,-1),(1,0),(0,1),(-1,0)];dirs8=dirs4+[(1,1),(-1,1),(1,-1),(-1,-1)];dirs=dirs4 if neigh=='4' else dirs8
    for it in range(iters):
        old=B[:]
        for y in range(h):
          for x in range(w):
            src=B if inplace else old
            vals=[src[((y+dy)%h)*w+((x+dx)%w)] for dx,dy in dirs]
            avg=sum(vals)/len(vals)
            B[y*w+x]=(1-alpha)*src[y*w+x]+alpha*avg
    return B
def score(data,w,h,**kw):
    err=0;ex=0;cnt=0
    for A,f,M in data:
        B=smooth(A,w,h,**kw);mx=max(B)
        for v,ff in zip(B,f):
            pred=int(math.floor(v/mx*M+0.5));err+=(pred-ff)**2;ex+=pred==ff;cnt+=1
    return err/cnt,ex/cnt
for (w,h) in [(3,3),(4,4),(2,2),(4,3),(3,4)]:
    data=get_data(w,h,range(1,61));print("size",w,h)
    results=[]
    for neigh in ['4','8']:
      for inplace in [True,False]:
       for iters in range(1,11):
        for alpha in [i/20 for i in range(1,21)]:
            sc=score(data,w,h,iters=iters,alpha=alpha,neigh=neigh,inplace=inplace)
            results.append((sc,neigh,inplace,iters,alpha))
    results.sort(key=lambda z:z[0][0]);print(results[:8])
