    paths=[[None]*W for _ in range(H)]; idx=[0]
    def process(x,y,w,h,path):
        ws=segments(w);hs=segments(h);cy=y
        for sh in hs:
            if sh==0:continue
            cx=x
            for sw in ws:
                if sw==0:continue
                my=idx[0];idx[0]+=1;newpath=path+[my]
                if sw==1 and sh==1:
                    paths[cy][cx]=newpath
                else:
                    process(cx,cy,sw,sh,newpath)
                cx+=sw
            cy+=sh
    process(0,0,W,H,[])
    return paths,idx[0]
