    return data

def eval1(n,data,model,gamma=1.5,alpha=1.0):
    paths,L=build_paths(1,n);sstart=4+2*(L+1);err=0;ex=0;cnt=0
    for p,s,raw in data:
      for finals,start,M in [(p,4,max(p)),(s,sstart,max(s))]:
        U=[raw[start+2*i]/4294967296 for i in range(L)];Z=[]
        for x in range(n):
            vals=[U[i] for i in paths[0][x]]
            if model=='mean':z=(sum(vals)/len(vals))**gamma
            elif model=='sum_pow_each':z=sum(v**gamma for v in vals)
            elif model=='prod':z=math.prod(vals)**gamma
            elif model=='geomean':z=(math.prod(vals)**(1/len(vals)))**gamma
            elif model=='weighted_pow_each':z=alpha*(vals[0]**gamma)+(vals[-1]**gamma if len(vals)>1 else vals[0]**gamma)
            elif model=='weighted_mean':z=((alpha*vals[0]+(vals[-1] if len(vals)>1 else vals[0]))/(alpha+1))**gamma
            elif model=='leaf':z=vals[-1]**gamma
            Z.append(z)
        B=[]
        for i in range(n):
            tot=0
            for dx,w in [(-2,.01),(-1,.2),(0,1),(1,.2),(2,.01)]:tot+=w*Z[(i+dx)%n]
            B.append(tot)
        mx=max(B)
        for v,f in zip(B,finals):
            pred=int(math.floor(v/mx*M+.5));err+=(pred-f)**2;ex+=pred==f;cnt+=1
    return err/cnt,ex/cnt
for n in [5,8,10,16,20]:
    data=dataset1(n,range(1,61));paths,L=build_paths(1,n);print("n",n,"L",L,"paths",paths[0])
    for model in ['mean','sum_pow_each','prod','geomean','leaf']:
        print(model,eval1(n,data,model))
    for model in ['weighted_pow_each','weighted_mean']:
        res=[]
        for ai in range(0,21):res.append((eval1(n,data,model,alpha=ai/10),ai/10))
        res.sort(key=lambda z:z[0][0]);print(model,res[:3])
