import pickle,math,sys,random
sys.path.insert(0,'/tmp')
exec(open('/tmp/fit_tree.py').read().split('def dataset')[0])

def eval8(p_off,q_off,gamma):
    paths,L=build_paths(8,8);fp,fs,raws=pickle.load(open('/tmp/treedata_8x8.pkl','rb'));sstart=4+2*(L+1);err=0;ex=0;cnt=0
    for finals,start in [(fp,4),(fs,sstart)]:
      for j,f in enumerate(finals):
        U=[raws[j][start+2*i]/4294967296 for i in range(L)];Z=[]
        for y in range(8):
          for x in range(8):
            c,l=[U[i] for i in paths[y][x]];Z.append(((p_off+c)*(q_off+l))**gamma)
        B=[]
        for y in range(8):
          for x in range(8):
            tot=0
            for dy in range(-2,3):
              for dx in range(-2,3):
                w={0:1,1:.2,2:.02,4:.01}.get(dx*dx+dy*dy,0);tot+=w*Z[((y+dy)%8)*8+((x+dx)%8)]
            B.append(tot)
        mx=max(B);M=max(f)
        for v,ff in zip(B,f):
            pred=int(math.floor(v/mx*M+.5));err+=(pred-ff)**2;ex+=pred==ff;cnt+=1
    return err/cnt,ex/cnt
results=[]
for gamma in [0.5,0.75,1,1.25,1.5,1.75,2]:
  for pi in range(0,11):
    for qi in range(0,11):
        sc=eval8(pi/10,qi/10,gamma);results.append((sc,gamma,pi/10,qi/10))
  print("done gamma",gamma,flush=True)
results.sort(key=lambda z:z[0][0]);print(results[:20])
