import pickle,math
fp,fs,raws=pickle.load(open('/tmp/treedata_8x8.pkl','rb'))
def corr(xs,ys):
    n=len(xs);mx=sum(xs)/n;my=sum(ys)/n;num=sum((x-mx)*(y-my) for x,y in zip(xs,ys));den=math.sqrt(sum((x-mx)**2 for x in xs)*sum((y-my)**2 for y in ys));return num/den if den else 0
# combine prod+str as separate samples: finals list 120, latent values per field start
samples=[]
for finals,start in [(fp,4),(fs,166)]:
    for j,f in enumerate(finals):
        U=[raws[j][start+2*i]/4294967296 for i in range(80)];samples.append((U,f))
for latent in [0,1,2,5,6,20,40]:
    print("latent",latent)
    xs=[U[latent] for U,f in samples]
    for y in range(8):
        row=[]
        for x in range(8):
            row.append(corr(xs,[f[y*8+x]/max(f) for U,f in samples]))
        print([round(v,2) for v in row])
