import sys,subprocess,math
sys.path.insert(0,'/tmp')
from getfast import get,parse
# build 2D stencil matrix for 1x8 (W=1,H=8) B=KZ with offsets dx,dy -2..2, x wraps in width1
W=1;H=8;N=8
def wd(d2):return {0:1,1:.2,2:.02,4:.01}.get(d2,0)
K=[[0.0]*N for _ in range(N)]
for y in range(H):
  for x in range(W):
    i=y*W+x
    for dy in range(-2,3):
      for dx in range(-2,3):
        w=wd(dx*dx+dy*dy)
        if w:K[i][((y+dy)%H)*W+((x+dx)%W)]+=w
print("K rows")
for r in K:print([round(x,2) for x in r])
# invert
M=[row[:]+[1.0 if i==j else 0.0 for j in range(N)] for i,row in enumerate(K)]
for col in range(N):
    piv=max(range(col,N),key=lambda r:abs(M[r][col]));M[col],M[piv]=M[piv],M[col];pv=M[col][col]
    for j in range(2*N):M[col][j]/=pv
    for r in range(N):
        if r!=col and M[r][col]:
            f=M[r][col]
            for j in range(2*N):M[r][j]-=f*M[col][j]
Kinv=[row[N:] for row in M]
# paths for 1x8: segments along height [2,2,2,2], width [1,0,0,0]; latents: coarse0 leaves1,2; coarse3 leaves4,5; etc.
rows=[]
for seed in range(1,61):
    r,caps=get(1,8,seed,1);pid,wh,p,o,s=parse(caps[0]);raw=list(map(int,subprocess.check_output(['/tmp/mtseq',str(seed),'500']).split()))
    for finals,start in [(s,30)]: # strength only, sstart for L12 =4+2*13=30
        U=[raw[start+2*i]/4294967296 for i in range(12)];ratio=[v/max(finals) for v in finals];Z=[sum(Kinv[i][k]*ratio[k] for k in range(N)) for i in range(N)]
        for cell in range(8):
            block=cell//2;coarse=U[block*3];leaf=U[block*3+1+(cell%2)];rows.append((cell%2,coarse,leaf,Z[cell]))
# Fit candidate functions with per-seed scale? Z here is already scaled by 1/maxB per seed; candidate should be proportional within each seed, not across. Our rows lost seed grouping for scale; redo grouping in scoring below by storing seed index.
