import pickle,math
fp,fs,raws=pickle.load(open('/tmp/fastdata_4x4.pkl','rb'))
def eval_model(order,gamma,w1=.2,w2=.02,w4=.01):
    err=0;ex=0;cnt=0
    for finals,start in [(fp,4),(fs,38)]:
      for j,f in enumerate(finals):
        A=[raws[j][start+2*i]/4294967296 for i in range(16)];B=[]
        for y in range(4):
          for x in range(4):
            tot=0
            for dy in range(-2,3):
              for dx in range(-2,3):
                w={0:1,1:w1,2:w2,4:w4}.get(dx*dx+dy*dy,0);val=A[((y+dy)%4)*4+((x+dx)%4)];tot+=w*(val**gamma if order=='before' else val)
            B.append(tot if order=='before' else tot**gamma)
        mx=max(B);M=max(f)
        for v,ff in zip(B,f):
            p=int(math.floor(v/mx*M+.5));err+=(p-ff)**2;ex+=p==ff;cnt+=1
    return err/cnt,ex/cnt
for order in ['before','after']:
  for gamma in [0.5,1,1.5,2,3]:print(order,gamma,eval_model(order,gamma))
