    seen=[]
    for cell in range(n):
        top=paths[cell][0][0]
        if top not in seen:seen.append(top);segments.append([])
        segments[seen.index(top)].append(cell)
    coarse_idx=seen
    for p,s,raw in data:
      for finals,start,M in [(p,4,max(p)),(s,sstart,max(s))]:
        U=[raw[start+2*i]/4294967296 for i in range(L)]
