        # effective coarse per segment
        if 'smooth1d' in mode:
            ceff=smooth1([c**1.5 for c in coarse_raw],[.01,.2,1,.2,.01])
            # convert ceff back? We'll use as multiplier directly in formulas below by setting coarse values to ceff and then not pow again: hack via mode flags
        elif 'smooth2d' in mode:
            # effective 1D kernel from 2D stencil on 1 row of length = num segments: compute with offsets dx,dy and width1? For a 1 x m field, K row weights [1.42,.24,.01...] depending m; use smooth with [0.01,0.24,1.42,0.24,0.01] (scale cancels)
            ceff=smooth1([c**1.5 for c in coarse_raw],[.01,.24,1.42,.24,.01])
        else:
            ceff=[c**1.5 for c in coarse_raw]
        # map ceff to cells
        Ccell=[0]*n
        for si,seg in enumerate(segments):
            for cell in seg:Ccell[cell]=ceff[si]
        if mode.startswith('prod_after'):
            # B = K(leaf^1.5) * Ccell
            Lf=smooth1([x**1.5 for x in leaf],[.01,.24,1.42,.24,.01]) # 2D effective kernel for 1D? Wait final kernel in earlier eval used full 2D offsets, equivalent to this for W=1
            B=[Lf[i]*Ccell[i] for i in range(n)]
        elif mode.startswith('sum_after'):
            Lf=smooth1([x**1.5 for x in leaf],[.01,.24,1.42,.24,.01]);B=[Lf[i]+Ccell[i] for i in range(n)]
        else:
            # product before final blur: Z=leaf^1.5 * Ccell, then K
            Z=[(leaf[i]**1.5)*Ccell[i] for i in range(n)];B=smooth1(Z,[.01,.24,1.42,.24,.01])
        mx=max(B)
        for v,f in zip(B,finals):
            pred=int(math.floor(v/mx*M+.5));err+=(pred-f)**2;ex+=pred==f;cnt+=1
    return err/cnt,ex/cnt
