import sys,math
sys.path.insert(0,'/tmp')
exec(open('/tmp/fit1dtree.py').read().split("for n in [5,8")[0])

def eval_blocknorm(n,data,mode):
    paths,L=build_paths(1,n);sstart=4+2*(L+1);err=0;ex=0;cnt=0
    # groups by top latent index (path[0]) for depth>1; singleton group is itself
    groups={}
    for cell in range(n):groups.setdefault(paths[cell][0][0],[]).append(cell)
    for p,s,raw in data:
      for finals,start,M in [(p,4,max(p)),(s,sstart,max(s))]:
        U=[raw[start+2*i]/4294967296 for i in range(L)];Z=[0]*n
        for top,cells in groups.items():
            c=U[top]; leaves=[U[paths[cell][0][-1]] for cell in cells]
            if len(cells)==1:
                Z[cells[0]]=leaves[0]**1.5;continue
            if mode=='norm_pow_after': # (c * leaf/mean(leaf))^1.5
                mean=sum(leaves)/len(leaves);vals=[(c*l/mean)**1.5 for l in leaves]
            elif mode=='norm_pow_before': # c^1.5 * leaf^1.5/mean(leaf^1.5)
                lp=[l**1.5 for l in leaves];mean=sum(lp)/len(lp);vals=[(c**1.5)*(v/mean) for v in lp]
            elif mode=='norm_sum_pow': # c^1.5 * leaf^1.5 / sum(leaf^1.5) * len
                lp=[l**1.5 for l in leaves];mean=sum(lp)/len(lp);vals=[(c**1.5)*(v/mean) for v in lp]
            elif mode=='share': # Z = c^1.5 * (leaf/sum leaves) * something (scale cancels globally? use *len)
                vals=[(c**1.5)*(l/sum(leaves))*len(leaves) for l in leaves]
            elif mode=='share_pow': vals=[(c*(l/sum(leaves))*len(leaves))**1.5 for l in leaves]
            for cell,v in zip(cells,vals):Z[cell]=v
        B=[]
        for i in range(n):
            tot=0
            for dy in range(-2,3):
              for dx in range(-2,3):
                w={0:1,1:.2,2:.02,4:.01}.get(dx*dx+dy*dy,0);tot+=w*Z[(i+dy)%n]
            B.append(tot)
        mx=max(B)
        for v,f in zip(B,finals):
            pred=int(math.floor(v/mx*M+.5));err+=(pred-f)**2;ex+=pred==f;cnt+=1
    return err/cnt,ex/cnt
for n in [5,8,16]:
    data=dataset1(n,range(1,61));print('n',n)
    for mode in ['norm_pow_after','norm_pow_before','share','share_pow']:print(mode,eval_blocknorm(n,data,mode))
