import sys,math,random
sys.path.insert(0,'/tmp')
exec(open('/tmp/fit1dtree.py').read().split("for n in [5,8")[0])

def eval_kernel(n,data,eff):
    # eff list for offset distance 0..len-1 as stencil offsets (not distinct cells): B_i=sum_{d=-R..R} eff[abs(d)] Z_{i+d}
    paths,L=build_paths(1,n);sstart=4+2*(L+1);err=0;ex=0;cnt=0
    for p,s,raw in data:
      for finals,start,M in [(p,4,max(p)),(s,sstart,max(s))]:
        U=[raw[start+2*i]/4294967296 for i in range(L)];Z=[]
        for cell in range(n):
            vals=[U[i] for i in paths[cell][0]];Z.append(math.prod(vals)**1.5)
        B=[]
        R=len(eff)-1
        for i in range(n):B.append(sum(eff[abs(d)]*Z[(i+d)%n] for d in range(-R,R+1)))
        mx=max(B)
        for v,f in zip(B,finals):
            pred=int(math.floor(v/mx*M+.5));err+=(pred-f)**2;ex+=pred==f;cnt+=1
    return err/cnt,ex/cnt
