import sys,math
sys.path.insert(0,'/tmp')
exec(open('/tmp/fit1dtree.py').read().split("for n in [5,8")[0])

def eval_blockmax(n,data,mode):
    paths,L=build_paths(1,n);sstart=4+2*(L+1);err=0;ex=0;cnt=0
    groups={}
    for cell in range(n):groups.setdefault(paths[cell][0][0],[]).append(cell)
    for p,s,raw in data:
      for finals,start,M in [(p,4,max(p)),(s,sstart,max(s))]:
        U=[raw[start+2*i]/4294967296 for i in range(L)];Z=[0]*n
        for top,cells in groups.items():
            leaves=[U[paths[cell][0][-1]] for cell in cells];lp=[l**1.5 for l in leaves]
            if len(cells)==1:
                Z[cells[0]]=lp[0];continue
            c=U[top]
            if mode=='max':scale=(c**1.5)/max(lp)
            elif mode=='mean':scale=(c**1.5)/(sum(lp)/len(lp))
            elif mode=='sum':scale=(c**1.5)/sum(lp)
            elif mode=='max_raw':scale=c/max(leaves)  # then Z=lp*scale, not ^1.5 on c
            for cell,v in zip(cells,lp):Z[cell]=v*scale
        B=[]
        for i in range(n):
            tot=0
            for dy in range(-2,3):
              for dx in range(-2,3):
                w={0:1,1:.2,2:.02,4:.01}.get(dx*dx+dy*dy,0);tot+=w*Z[(i+dy)%n]
            B.append(tot)
        mx=max(B)
        for v,f in zip(B,finals):
            pred=int(math.floor(v/mx*M+.5));err+=(pred-f)**2;ex+=pred==f;cnt+=1
    return err/cnt,ex/cnt
for n in [5,8,16,10]:
    data=dataset1(n,range(1,61));print('n',n)
    for mode in ['max','mean','sum','max_raw']:print(mode,eval_blockmax(n,data,mode))
