{"command":"cat > main.cpp << 'EOF'
#include <bits/stdc++.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <poll.h>
#include <fcntl.h>
#include <signal.h>
#include <thread>
#include <mutex>
#include <chrono>

// ---------- Utility ----------
static std::string trimTrailingCR(const std::string &s) {
    if (!s.empty() && s.back()=='\r') return s.substr(0,s.size()-1);
    return s;
}
static std::string jsonEscape(const std::string &s) {
    std::string out;
    for (unsigned char c: s) {
        switch(c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\b': out += "\\b"; break;
            case '\f': out += "\\f"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if (c < 0x20) {
                    char buf[8]; snprintf(buf,sizeof(buf),"\\u%04x",c); out += buf;
                } else out.push_back((char)c);
        }
    }
    return out;
}

// ---------- TCLAP-like output ----------
static std::string g_prog;
static const int MAXWIDTH = 75;
static void spacePrint(std::ostream &os, const std::string &s, int indentSpaces, int secondLineOffset) {
    int maxWidth = MAXWIDTH;
    size_t len = s.length();
    size_t current = 0;
    int offset = indentSpaces;
    while (current < len) {
        // number of chars we can print on this line
        size_t avail = (size_t)std::max(1, maxWidth - offset);
        size_t stringLen = std::min(len - current, avail);
        if (stringLen < len - current) {
            size_t saved = stringLen;
            while (stringLen > 0 && s[current+stringLen] != ' ' && s[current+stringLen] != ',' ) {
                // TCLAP breaks at spaces; also allow break after comma? For our texts spaces suffice, but keep simple: only spaces
                if (s[current+stringLen] == ' ') break;
                stringLen--;
            }
            if (stringLen == 0) stringLen = saved;
        }
        for (int i=0;i<offset;i++) os << ' ';
        os << s.substr(current, stringLen);
        os << '\n';
        current += stringLen;
        while (current < len && s[current] == ' ') current++;
        offset = secondLineOffset;
    }
}
static std::string usageString() {
    return std::string("[-i <path to directory>] [-s <positive integer>] [-d <a string containing two space-seprated positive integers>] [-n <{1,2,3,4,5,6}>] [-r] [-t] [-o] [-q] [--] [--version] [-h] <Array of strings> ...");
}
static void printBriefUsage(std::ostream &os) {
    os << "Brief USAGE: \n";
    std::string full = g_prog + "  " + usageString();
    // TCLAP prints prog then usage with second line offset = prog length + 5? Observed indent 3, offset = 3+len(prog)+2
    spacePrint(os, full, 3, (int)g_prog.length() + 5);
    os << "\n";
}
static void printHelp() {
    std::ostream &os = std::cout;
    os << "\nUSAGE: \n\n";
    std::string full = g_prog + "  " + usageString();
    spacePrint(os, full, 3, (int)g_prog.length() + 5);
    os << "\n\nWhere: \n\n";
    struct Item { const char* id; const char* desc; };
    std::vector<Item> items = {
        {"-i <path to directory>,  --replaydirectory <path to directory>", "The path to directory for replay output."},
        {"-s <positive integer>,  --seed <positive integer>", "The seed for the map generator."},
        {"-d <a string containing two space-seprated positive integers>,  --dimensions <a string containing two space-seprated positive integers>", "The dimensions of the map."},
        {"-n <{1,2,3,4,5,6}>,  --nplayers <{1,2,3,4,5,6}>", "Create a map that will accommodate n players [SINGLE PLAYER MODE ONLY]."},
        {"-r,  --noreplay", "Turns off the replay generation."},
        {"-t,  --timeout", "Causes game environment to ignore timeouts (give all bots infinite time)."},
        {"-o,  --override", "Overrides player-sent names using cmd args [SERVER ONLY]."},
        {"-q,  --quiet", "Runs game in quiet mode, producing machine-parsable output."},
        {"--,  --ignore_rest", "Ignores the rest of the labeled arguments following this flag."},
        {"--version", "Displays version information and exits."},
        {"-h,  --help", "Displays usage information and exits."},
        {"<Array of strings>  (accepted multiple times)", "Start commands for bots."},
    };
    for (auto &it: items) {
        spacePrint(os, it.id, 3, 6);
        spacePrint(os, it.desc, 5, 5);
        os << "\n";
    }
    os << "\n   Halite Game Environment\n\n";
}
static void printVersion() {
    std::cout << "\n" << g_prog << "  version: 1.2\n\n";
}
struct ParseError {
    std::string arg;
    std::string msg;
};
[[noreturn]] static void throwParse(const std::string &arg, const std::string &msg) {
    throw ParseError{arg,msg};
}
static void outputParseError(const ParseError &e) {
    std::ostream &os = std::cerr;
    os << "PARSE ERROR: Argument: " << e.arg << "\n";
    os << "             " << e.msg << "\n\n";
    printBriefUsage(os);
    os << "For complete USAGE and HELP type: \n";
    os << "   " << g_prog << " --help\n\n";
}

// Value reading like TCLAP ReadValue: stream >> value; if fail or any char remains (is.get), error.
template<typename T>
static T readValueStr(const std::string &argId, const std::string &valStr) {
    std::stringstream is(valStr);
    T v;
    is >> v;
    if (!is) throwParse(argId, "Couldn't read argument value from string '" + valStr + "'");
    char c;
    if (is.get(c)) throwParse(argId, "Couldn't read argument value from string '" + valStr + "'");
    return v;
}
struct Dimensions {
    unsigned short width = 0;
    unsigned short height = 0;
};
static std::istream& operator>>(std::istream &is, Dimensions &d) {
    int w=0,h=0;
    is >> w;
    if (!is) return is;
    is >> h;
    if (!is) return is;
    d.width = (unsigned short)w;
    d.height = (unsigned short)h;
    return is;
}

// ---------- Game types ----------
struct Cell { unsigned char owner=0; unsigned char strength=0; };
struct Frame { std::vector<std::vector<Cell>> cells; }; // [y][x]
struct GameMapData {
    int width=0,height=0;
    std::vector<std::vector<unsigned char>> productions; // [y][x]
    Frame initial;
};

// ---------- Map generation ----------
struct MapGenerator {
    std::mt19937 rng;
    unsigned int seed;
    int reqW, reqH;
    int numPlayers; // effective map players
    bool axisFlip=false;
    MapGenerator(unsigned int s,int w,int h,int p):rng(s),seed(s),reqW(w),reqH(h),numPlayers(p){}
    double nextDouble() {
        uint64_t hi = rng();
        uint64_t lo = rng();
        uint64_t combined = (hi<<32)|lo;
        return (double)combined / 18446744073709551616.0;
    }
    // partition helpers
    static std::vector<int> segments4(int n) {
        std::vector<int> v;
        int base=n/4, rem=n%4;
        for(int i=0;i<4;i++){int sz=base+(i<rem?1:0); if(sz>0) v.push_back(sz);}
        return v;
    }
    // Build paths: for each cell, list of latent indices along recursive partition (preorder, root divided into 4x4)
    struct PathBuilder {
        std::vector<std::vector<std::vector<int>>> paths; // [y][x]
        int idx=0;
        PathBuilder(int W,int H){paths.assign(H, std::vector<std::vector<int>>(W));}
        void process(int x,int y,int w,int h,std::vector<int> path){
            auto ws=segments4(w); auto hs=segments4(h);
            int cy=y;
            for(int sh: hs){
                int cx=x;
                for(int sw: ws){
                    int my=idx++;
                    auto np=path; np.push_back(my);
                    if(sw==1 && sh==1){ paths[cy][cx]=np; }
                    else process(cx,cy,sw,sh,np);
                    cx+=sw;
                }
                cy+=sh;
            }
        }
    };
    // Generate a single field (productions or strengths are generated as two fields by caller with shared rng sequence)
    // This function generates latents, then caller handles extra/max to match sequence. Here we generate both fields together in generate()
    static double kernelW(int dx,int dy){
        int d2=dx*dx+dy*dy;
        if(d2==0) return 1.0;
        if(d2==1) return 0.2;
        if(d2==2) return 0.02;
        if(d2==4) return 0.01;
        return 0.0;
    }
    std::vector<std::vector<unsigned char>> fieldFromLatents(const std::vector<double>& U,
        const std::vector<std::vector<std::vector<int>>>& paths,int W,int H,int maxVal){
        std::vector<double> Z((size_t)W*H,0);
        for(int y=0;y<H;y++) for(int x=0;x<W;x++){
            double prod=1.0;
            for(int id: paths[y][x]) prod *= U[(size_t)id];
            Z[(size_t)y*W+x]=std::pow(prod,1.5);
        }
        std::vector<double> B((size_t)W*H,0);
        for(int y=0;y<H;y++) for(int x=0;x<W;x++){
            double tot=0;
            for(int dy=-2;dy<=2;dy++) for(int dx=-2;dx<=2;dx++){
                double w=kernelW(dx,dy); if(w==0) continue;
                int nx=(x+dx)%W; if(nx<0)nx+=W;
                int ny=(y+dy)%H; if(ny<0)ny+=H;
                tot += w * Z[(size_t)ny*W+nx];
            }
            B[(size_t)y*W+x]=tot;
        }
        double mx=0; for(double v:B) mx=std::max(mx,v);
        std::vector<std::vector<unsigned char>> out(H, std::vector<unsigned char>(W,0));
        for(int y=0;y<H;y++) for(int x=0;x<W;x++){
            double v = (mx>0? B[(size_t)y*W+x]/mx * maxVal : 0);
            long iv = std::lround(v);
            if(iv<0)iv=0; if(iv>255)iv=255;
            out[y][x]=(unsigned char)iv;
        }
        return out;
    }
    // Generate tile fields; assumes rng already at latent start (setup consumed by generate())
    void generateTileFields(int W,int H,
        std::vector<std::vector<unsigned char>>& prodOut,
        std::vector<std::vector<unsigned char>>& strOut){
        if(W==1 && H==1){
            (void)nextDouble(); // one pair before maxes (matches 1x1 sequence)
            int mp = 6 + (int)(rng()%10);
            int ms = 150 + (int)(rng()%106);
            prodOut.assign(1, std::vector<unsigned char>(1,(unsigned char)mp));
            strOut.assign(1, std::vector<unsigned char>(1,(unsigned char)ms));
            return;
        }
        PathBuilder pb(W,H); pb.process(0,0,W,H,{});
        int L=pb.idx;
        std::vector<double> Up((size_t)L), Us((size_t)L);
        for(int i=0;i<L;i++) Up[(size_t)i]=nextDouble();
        (void)nextDouble(); // extra pair between fields
        for(int i=0;i<L;i++) Us[(size_t)i]=nextDouble();
        int mp = 6 + (int)(rng()%10);
        int ms = 150 + (int)(rng()%106);
        prodOut = fieldFromLatents(Up,pb.paths,W,H,mp);
        strOut = fieldFromLatents(Us,pb.paths,W,H,ms);
    }
    static int floorTo(int v,int m){ if(m<=1) return v; int r=v - (v%m); return r==0? m : r; }
    GameMapData generate(){
        // setup draws (4)
        uint32_t d0 = rng();
        axisFlip = (d0 % 2u)!=0;
        uint32_t setup1 = rng();
        uint32_t setup2 = rng();
        uint32_t setup3 = rng();
        (void)setup1;(void)setup2;(void)setup3;
        int W=reqW,H=reqH;
        // dimension adjustment
        switch(numPlayers){
            case 2: W=floorTo(W,2); H=floorTo(H,2); break;
            case 3: W=floorTo(W,3); H=floorTo(H,3); break;
            case 5: W=floorTo(W,5); H=floorTo(H,5); break;
            case 4:
                if(!axisFlip){W=floorTo(W,8);H=floorTo(H,2);}else{W=floorTo(W,2);H=floorTo(H,8);}break;
            case 6:
                if(!axisFlip){W=floorTo(W,12);H=floorTo(H,3);}else{W=floorTo(W,3);H=floorTo(H,12);}break;
            default: break;
        }
        GameMapData md; md.width=W; md.height=H;
        md.productions.assign((size_t)H, std::vector<unsigned char>((size_t)W,0));
        md.initial.cells.assign((size_t)H, std::vector<Cell>((size_t)W));
        // Determine tile dimensions and placements
        struct Place {int ox,oy; int flipx; int flipy; int shiftx; int player;};
        // flipx/flipy 0/1, shiftx for translation strips (cyclic x shift)
        int tw=W, th=H;
        std::vector<Place> places;
        int P=numPlayers;
        if(P<=1){ tw=W;th=H; places.push_back({0,0,0,0,0,1}); }
        else if(P==2){
            if(!axisFlip){ tw=W; th=H/2; places.push_back({0,0,0,0,0,1}); places.push_back({0,th,0,1,0,2}); }
            else { tw=W/2; th=H; places.push_back({0,0,0,0,0,1}); places.push_back({tw,0,1,0,0,2}); }
        } else if(P==4){
            tw=W/2; th=H/2;
            places.push_back({0,0,0,0,0,1}); places.push_back({tw,0,1,0,0,2}); places.push_back({0,th,0,1,0,3}); places.push_back({tw,th,1,1,0,4});
        } else if(P==6){
            if(!axisFlip){ tw=W/2; th=H/3; int pid=1; for(int r=0;r<3;r++){ places.push_back({0,r*th,0,0,0,pid++}); places.push_back({tw,r*th,1,0,0,pid++}); } }
            else { tw=W/3; th=H/2; int pid=1; for(int c=0;c<3;c++) places.push_back({c*tw,0,0,0,0,pid++}); pid=4; for(int c=0;c<3;c++) places.push_back({c*tw,th,0,1,0,pid++}); }
        } else if(P==3 || P==5){
            // translation strips; shift step from setup1
            int step = (int)(setup1 % (uint32_t)P);
            if(!axisFlip){
                tw=W; th=H/P;
                int shiftUnit = W/P;
                for(int k=0;k<P;k++){
                    int strip = (k* (step==0?1:step)) % P; // not exactly original; place by player order below
                    (void)strip;
                }
                // place strips in order, player assigned by generator step: player at strip s is ((s * inv?) ) - simplify: assign players by iterating generator
                std::vector<int> playerAtStrip(P,0);
                int gstep = step; if(gstep==0) gstep=1;
                // generator in terms of (dx in units of W/P, dy in units of H/P): use dx=gstep, dy=1
                for(int k=0;k<P;k++){ int s=(k*1)%P; playerAtStrip[(size_t)s]=k+1; }
                for(int s=0;s<P;s++){ int shift = (s*gstep*shiftUnit)%W; places.push_back({0,s*th,0,0,shift,playerAtStrip[(size_t)s]}); }
            } else {
                tw=W/P; th=H;
                int shiftUnit = H/P;
                int gstep = step; if(gstep==0) gstep=1;
                std::vector<int> playerAtStrip(P,0);
                for(int k=0;k<P;k++){ int s=k%P; playerAtStrip[(size_t)s]=k+1; }
                // shift encoded in shiftx field but interpreted as y-shift for vertical strips below (we use a flag via tw!=W)
                for(int s=0;s<P;s++){ int shift=(s*gstep*shiftUnit)%H; places.push_back({s*tw,0,0,0,shift,playerAtStrip[(size_t)s]}); }
            }
        }
        if(tw<=0) tw=1; if(th<=0) th=1;
        std::vector<std::vector<unsigned char>> tileProd, tileStr;
        generateTileFields(tw,th,tileProd,tileStr);
        // Assemble
        for(int y=0;y<H;y++) for(int x=0;x<W;x++){
            // find place containing (x,y)
            int lx=x, ly=y;
            bool found=false;
            for(auto &pl: places){
                if(P==3 || P==5){
                    if(!axisFlip){
                        if(y>=pl.oy && y<pl.oy+th){ ly=y-pl.oy; lx=(x-pl.shiftx)%W; if(lx<0)lx+=W; found=true; break; }
                    } else {
                        if(x>=pl.ox && x<pl.ox+tw){ lx=x-pl.ox; ly=(y-pl.shiftx)%H; if(ly<0)ly+=H; found=true; break; }
                    }
                } else {
                    if(x>=pl.ox && x<pl.ox+tw && y>=pl.oy && y<pl.oy+th){
                        lx = pl.flipx? (tw-1-(x-pl.ox)) : (x-pl.ox);
                        ly = pl.flipy? (th-1-(y-pl.oy)) : (y-pl.oy);
                        found=true; break;
                    }
                }
            }
            if(!found){ lx=std::min(x,tw-1); ly=std::min(y,th-1); }
            md.productions[(size_t)y][(size_t)x]=tileProd[(size_t)ly][(size_t)lx];
            md.initial.cells[(size_t)y][(size_t)x].owner=0;
            md.initial.cells[(size_t)y][(size_t)x].strength=tileStr[(size_t)ly][(size_t)lx];
        }
        // Player starts: base center of tile
        int bx = tw/2, by = th/2;
        // For translation, only place actual bot players? Map accommodates P, but starts are for all P positions then filtered by caller? Original: in single-player mode with -n, only player 1 is placed (others are empty). We'll return starts in initial by placing all P, caller will clear extras if needed. Store starts encoded as owners for now.
        for(auto &pl: places){
            int sx,sy;
            if(P==3 || P==5){
                if(!axisFlip){ sx=(bx+pl.shiftx)%W; sy=pl.oy+by; }
                else { sx=pl.ox+bx; sy=(by+pl.shiftx)%H; }
            } else {
                sx = pl.ox + (pl.flipx? (tw-1-bx): bx);
                sy = pl.oy + (pl.flipy? (th-1-by): by);
            }
            if(sx>=0&&sx<W&&sy>=0&&sy<H) md.initial.cells[(size_t)sy][(size_t)sx].owner=(unsigned char)pl.player;
        }
        return md;
    }
};

