static bool writeAllFd(int fd,const std::string& s){
    size_t off=0;
    while(off<s.size()){
        ssize_t n=::write(fd,s.data()+off,s.size()-off);
        if(n<0){ if(errno==EINTR) continue; return false; }
        off+=(size_t)n;
    }
    return true;
}
struct ReadResult { std::string response; bool error=false; long long elapsedMs=0; };
static ReadResult readLineTimeout(int fd,long long timeoutMs,bool ignoreTimeout){
    ReadResult rr;
    auto start=std::chrono::steady_clock::now();
    auto deadline = start + std::chrono::milliseconds(ignoreTimeout? (long long)4e12 : timeoutMs);
    std::string buf;
    // set nonblocking temporarily
    int flags=fcntl(fd,F_GETFL,0);
    fcntl(fd,F_SETFL,flags|O_NONBLOCK);
    while(true){
        auto now=std::chrono::steady_clock::now();
        if(now>=deadline){ rr.error=true; break; }
        long long remain=std::chrono::duration_cast<std::chrono::milliseconds>(deadline-now).count();
        int pollTimeout = ignoreTimeout? 1000 : (int)std::min<long long>(remain,1000);
        struct pollfd pfd{fd,POLLIN,0};
        int pr=poll(&pfd,1,pollTimeout);
        if(pr>0){
            char tmp[4096];
            ssize_t n=::read(fd,tmp,sizeof(tmp));
            if(n>0){
                for(ssize_t i=0;i<n;i++){
                    if(tmp[i]=='\n'){
                        buf.append(tmp,tmp+i);
                        // Note: any extra bytes after newline in this chunk are lost in this implementation;
                        // original reads byte-by-byte. To avoid loss, we should read byte-by-byte below.
                        rr.response=trimTrailingCR(buf);
                        rr.elapsedMs=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-start).count();
                        fcntl(fd,F_SETFL,flags);
                        return rr;
                    }
                }
                buf.append(tmp,tmp+n);
                // To avoid losing bytes after a newline that may have been in chunk, the loop above handled newline; if no newline continue.
            } else if(n==0){
                // EOF: original waits until deadline. Sleep a bit to avoid busy loop.
                std::this_thread::sleep_for(std::chrono::milliseconds(1));
            } else {
                if(errno!=EAGAIN && errno!=EWOULDBLOCK && errno!=EINTR){
                    std::this_thread::sleep_for(std::chrono::milliseconds(1));
                }
            }
        } else if(pr==0){
            if(ignoreTimeout) continue;
            // loop will check deadline
        } else {
            if(errno==EINTR) continue;
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    }
    fcntl(fd,F_SETFL,flags);
    rr.response=trimTrailingCR(buf);
    rr.elapsedMs=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-start).count();
    return rr;
}
// The chunk read above can lose bytes after newline if a bot pipelining extra lines in one write.
// Replace with byte-by-byte version for correctness (used by callers).
static ReadResult readLineTimeoutByte(int fd,long long timeoutMs,bool ignoreTimeout){
    ReadResult rr;
    auto start=std::chrono::steady_clock::now();
    auto deadline = start + std::chrono::milliseconds(ignoreTimeout? (long long)4e12 : timeoutMs);
    std::string buf;
    int flags=fcntl(fd,F_GETFL,0);
    fcntl(fd,F_SETFL,flags|O_NONBLOCK);
    while(true){
        auto now=std::chrono::steady_clock::now();
        if(now>=deadline){ rr.error=true; break; }
        long long remain=std::chrono::duration_cast<std::chrono::milliseconds>(deadline-now).count();
        int pollTimeout = ignoreTimeout? 1000 : (int)std::min<long long>(remain,1000);
        struct pollfd pfd{fd,POLLIN,0};
        int pr=poll(&pfd,1,pollTimeout);
        if(pr>0){
            char ch;
            ssize_t n=::read(fd,&ch,1);
            if(n==1){
                if(ch=='\n'){
                    rr.response=trimTrailingCR(buf);
                    rr.elapsedMs=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-start).count();
                    fcntl(fd,F_SETFL,flags);
                    return rr;
                } else buf.push_back(ch);
            } else if(n==0){
                std::this_thread::sleep_for(std::chrono::milliseconds(1));
            } else {
                if(errno!=EAGAIN && errno!=EWOULDBLOCK && errno!=EINTR) std::this_thread::sleep_for(std::chrono::milliseconds(1));
            }
        }
    }
    fcntl(fd,F_SETFL,flags);
    rr.response=trimTrailingCR(buf);
    rr.elapsedMs=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-start).count();
    return rr;
}
static const std::string LOG_SEPARATOR = std::string(77,'-');
static long long g_timestamp=0;
static std::string logFileNameFor(int id){ return std::to_string(id)+"-"+std::to_string(g_timestamp)+".log"; }
static void writeLogFile(BotProcess &bot){
    if(bot.logWritten) return;
    std::ofstream out(logFileNameFor(bot.id));
    out << bot.log;
    out.close();
    bot.logWritten=true;
}
static void killBotProcess(BotProcess &bot,bool drainRest=false){
    if(bot.pid>0){
        // kill process group
        kill(-bot.pid, SIGKILL);
        kill(bot.pid, SIGKILL);
    }
    if(drainRest && bot.fromFd>=0){
        // drain currently available output (nonblocking)
        int flags=fcntl(bot.fromFd,F_GETFL,0);
        fcntl(bot.fromFd,F_SETFL,flags|O_NONBLOCK);
        std::string rest;
        // small loop: poll with 0 timeout a few times
        for(int iter=0;iter<10;iter++){
            struct pollfd pfd{bot.fromFd,POLLIN,0};
            int pr=poll(&pfd,1,0);
            if(pr<=0) break;
            char tmp[4096]; ssize_t n=::read(bot.fromFd,tmp,sizeof(tmp));
            if(n>0) rest.append(tmp,tmp+n);
            else break;
        }
        fcntl(bot.fromFd,F_SETFL,flags);
        if(!rest.empty()){
            bot.log += "\n --- Bot was killed. Below is the rest of its output (if any): ---\n";
            bot.log += rest;
            bot.log += "\n --- End bot output ---";
        }
    }
    if(bot.pid>0){
        int status; waitpid(bot.pid,&status,WNOHANG);
    }
}
static bool launchBot(BotProcess &bot){
    int inPipe[2], outPipe[2];
    if(pipe(inPipe)<0 || pipe(outPipe)<0) return false;
    pid_t pid=fork();
    if(pid==0){
        setpgid(0,0);
        dup2(inPipe[0],0);
        dup2(outPipe[1],1);
        dup2(outPipe[1],2);
        close(inPipe[0]);close(inPipe[1]);close(outPipe[0]);close(outPipe[1]);
        execlp("sh","sh","-c",bot.command.c_str(),(char*)nullptr);
        _exit(127);
    }
    close(inPipe[0]); close(outPipe[1]);
    bot.pid=pid; bot.toFd=inPipe[1]; bot.fromFd=outPipe[0]; bot.launched=true;
    return pid>0;
}

