static std::string serializeMap(const Frame& fr,int W,int H){
    std::string s;
    // owners RLE flat
    int idx=0;
    while(idx<W*H){
        unsigned char owner=fr.cells[(size_t)idx/W][(size_t)idx%W].owner;
        int cnt=0;
        while(idx+cnt<W*H && fr.cells[(size_t)(idx+cnt)/W][(size_t)(idx+cnt)%W].owner==owner) cnt++;
        s += std::to_string(cnt); s.push_back(' ');
        s += std::to_string((int)owner); s.push_back(' ');
        idx+=cnt;
    }
    for(int y=0;y<H;y++) for(int x=0;x<W;x++){ s += std::to_string((int)fr.cells[(size_t)y][(size_t)x].strength); s.push_back(' '); }
    s.push_back('\n');
    return s;
}
static std::string serializeInit(int pid,const GameMapData& md){
    std::string s;
    s += std::to_string(pid); s.push_back('\n');
    s += std::to_string(md.width); s.push_back(' '); s += std::to_string(md.height); s += " \n";
    for(int y=0;y<md.height;y++) for(int x=0;x<md.width;x++){ s += std::to_string((int)md.productions[(size_t)y][(size_t)x]); s.push_back(' '); }
    s.push_back('\n');
    s += serializeMap(md.initial,md.width,md.height);
    return s;
}
static Frame processTurn(const Frame& cur,const std::vector<std::vector<unsigned char>>& moves,
    const std::vector<std::vector<unsigned char>>& prod,int W,int H){
    // production
    Frame src=cur;
    for(int y=0;y<H;y++) for(int x=0;x<W;x++){
        if(src.cells[(size_t)y][(size_t)x].owner!=0 && moves[(size_t)y][(size_t)x]==0){
            int ns=(int)src.cells[(size_t)y][(size_t)x].strength + (int)prod[(size_t)y][(size_t)x];
            if(ns>255)ns=255; src.cells[(size_t)y][(size_t)x].strength=(unsigned char)ns;
        }
    }
    // presence[y][x][owner]=strength
    std::vector<std::vector<std::map<int,int>>> pres((size_t)H, std::vector<std::map<int,int>>((size_t)W));
    for(int y=0;y<H;y++) for(int x=0;x<W;x++){
        auto c=cur.cells[(size_t)y][(size_t)x];
        if(c.owner==0){ if(c.strength>0) pres[(size_t)y][(size_t)x][0]=c.strength; }
        else pres[(size_t)y][(size_t)x][c.owner]=0;
    }
    const int DX[5]={0,0,1,0,-1}; const int DY[5]={0,-1,0,1,0};
    for(int y=0;y<H;y++) for(int x=0;x<W;x++){
        auto c=src.cells[(size_t)y][(size_t)x]; if(c.owner==0) continue;
        int d=moves[(size_t)y][(size_t)x]; int nx=x,ny=y;
        if(d>=1 && d<=4){ nx=(x+DX[d])%W; if(nx<0)nx+=W; ny=(y+DY[d])%H; if(ny<0)ny+=H; }
        int &ref=pres[(size_t)ny][(size_t)nx][c.owner];
        int nv=ref + c.strength; if(nv>255)nv=255; ref=nv;
    }
    Frame out; out.cells.assign((size_t)H, std::vector<Cell>((size_t)W));
    // combat
    for(int y=0;y<H;y++) for(int x=0;x<W;x++){
        std::map<int,int> surv;
        for(auto &kv: pres[(size_t)y][(size_t)x]){
            int owner=kv.first; int strength=kv.second; int dmg=0;
            for(auto &kv2: pres[(size_t)y][(size_t)x]) if(kv2.first!=owner) dmg+=kv2.second;
            if(owner!=0){
                const int ndx[4]={0,1,0,-1}; const int ndy[4]={-1,0,1,0};
                for(int dir=0;dir<4;dir++){
                    int nx=(x+ndx[dir])%W; if(nx<0)nx+=W; int ny=(y+ndy[dir])%H; if(ny<0)ny+=H;
                    for(auto &kv2: pres[(size_t)ny][(size_t)nx]) if(kv2.first!=0 && kv2.first!=owner) dmg+=kv2.second;
                }
            }
            int rem=strength-dmg;
            if(rem>0 || (strength==0 && dmg==0)) surv[owner]=std::max(rem,0);
        }
        int playerOwner=-1; int playerStr=0; int playerCount=0;
        for(auto &kv: surv) if(kv.first!=0){playerCount++; playerOwner=kv.first; playerStr=kv.second;}
        if(playerCount==1){ out.cells[(size_t)y][(size_t)x]={(unsigned char)playerOwner,(unsigned char)playerStr}; }
        else if(playerCount>1){
            int orig=cur.cells[(size_t)y][(size_t)x].owner;
            if(orig!=0 && surv.count(orig)) out.cells[(size_t)y][(size_t)x]={(unsigned char)orig,(unsigned char)surv[orig]};
            else { int mx=0; for(auto &kv:surv) if(kv.first!=0) mx=std::max(mx,kv.first); out.cells[(size_t)y][(size_t)x]={(unsigned char)mx,(unsigned char)surv[mx]}; }
        } else if(surv.count(0)){ out.cells[(size_t)y][(size_t)x]={0,(unsigned char)surv[0]}; }
        else out.cells[(size_t)y][(size_t)x]={0,0};
    }
    return out;
}
static int countTerritory(const Frame& fr,int pid,int W,int H){
    int c=0; for(int y=0;y<H;y++)for(int x=0;x<W;x++) if(fr.cells[(size_t)y][(size_t)x].owner==pid)c++; return c;
}
static int totalStrength(const Frame& fr,int pid,int W,int H){
    int c=0; for(int y=0;y<H;y++)for(int x=0;x<W;x++) if(fr.cells[(size_t)y][(size_t)x].owner==pid)c+=fr.cells[(size_t)y][(size_t)x].strength; return c;
}
