            if(token=="--version"){ printVersion(); return 0; }
            if(token=="-h" || token=="--help"){ printHelp(); return 0; }
            // Value args exact
            auto processValueArg = [&](const std::string& sh,const std::string& lo,auto&& setter){
                std::string id=argId(sh,lo);
                std::string key="-"+sh;
                if(alreadySet.count(key)) throwParse(id,"Argument already set!");
                if(i+1>=argc) throwParse(id,"Missing a value for this argument!");
                std::string val=argv[++i];
                setter(id,val);
                alreadySet.insert(key);
            };
            if(token=="-i" || token=="--replaydirectory"){
                processValueArg("i","replaydirectory",[&](const std::string&,const std::string&v){ replayDirectory=v; }); continue;
            }
            if(token=="-s" || token=="--seed"){
                processValueArg("s","seed",[&](const std::string&id,const std::string&v){ seed=readValueStr<unsigned int>(id,v); }); continue;
            }
            if(token=="-d" || token=="--dimensions"){
                processValueArg("d","dimensions",[&](const std::string&id,const std::string&v){ dimensions=readValueStr<Dimensions>(id,v); dimensionsSet=true; }); continue;
            }
            if(token=="-n" || token=="--nplayers"){
                processValueArg("n","nplayers",[&](const std::string&id,const std::string&v){ nplayers=readValueStr<int>(id,v); }); continue;
            }
            // switches exact
            auto processSwitch = [&](const std::string& sh,const std::string& lo,bool* ptr)->bool{
                if(token=="-"+sh || token=="--"+lo){
                    std::string id=argId(sh,lo); std::string key="-"+sh;
                    if(alreadySet.count(key)) throwParse(id,"Argument already set!");
                    alreadySet.insert(key); *ptr=true; return true;
                } return false;
            };
            if(processSwitch("r","noreplay",&noReplay)) continue;
            if(processSwitch("t","timeout",&ignoreTimeouts)) continue;
            if(processSwitch("o","override",&overrideNames)) continue;
            if(processSwitch("q","quiet",&quiet)) continue;
            // Long unmatched -> positional
            if(token.size()>=2 && token[0]=='-' && token[1]=='-'){ positional.push_back(token); continue; }
            // Single dash combined switches if any switch char present
            if(token.size()>1 && token[0]=='-' && token[1]!='-'){
                const std::string switchChars="rtoqh";
                bool hasSwitch=false;
                for(size_t k=1;k<token.size();k++) if(switchChars.find(token[k])!=std::string::npos) hasSwitch=true;
                if(hasSwitch){
                    std::string mutated=token;
                    struct Sw{char c; const char* lo; bool* ptr;};
                    std::vector<Sw> sws={{'r',"noreplay",&noReplay},{'t',"timeout",&ignoreTimeouts},{'o',"override",&overrideNames},{'q',"quiet",&quiet}};
                    // process in definition order r,t,o,q then h
                    for(auto &sw: sws){
                        for(size_t k=1;k<mutated.size();k++){
                            if(mutated[k]==sw.c){
                                std::string id=argId(std::string(1,sw.c),sw.lo);
                                if(alreadySet.count(std::string("-")+sw.c)) throwParse(id,"Argument already set!");
                                alreadySet.insert(std::string("-")+sw.c);
                                *sw.ptr=true;
                                mutated[k]='\a';
                            }
                        }
                    }
                    bool hasHelp=false;
                    for(size_t k=1;k<mutated.size();k++) if(mutated[k]=='h'){ hasHelp=true; mutated[k]='\a'; }
                    if(hasHelp){ printHelp(); return 0; }
                    bool remaining=false;
                    for(size_t k=1;k<mutated.size();k++) if(mutated[k]!='\a') remaining=true;
                    if(remaining) throwParse(mutated,"Couldn't find match for argument");
                    continue;
                } else { positional.push_back(token); continue; }
            }
            positional.push_back(token);
        }
    } catch(ParseError &e){
        outputParseError(e);
        return 1;
    }
    // Override handling
    std::vector<std::string> botCommands;
    std::vector<std::string> overrideNameList;
    if(overrideNames){
        if(positional.size()%2==1 || positional.size()<4){
            std::cout << "Invalid number of player parameters with override switch enabled.  Override intended for server use only.\n";
            return 1;
        }
        for(size_t i=0;i<positional.size();i+=2){ botCommands.push_back(positional[i]); overrideNameList.push_back(positional[i+1]); }
    } else {
        botCommands=positional;
    }
    if(botCommands.empty()){
        std::cout << "Please provide the launch command string for at least one bot.\nUse the --help flag for usage details.\n";
        return 1;
    }
    // Print bot commands (two sites)
    for(auto &cmd: botCommands){
        if(!quiet) std::cout << cmd << "\n";
        if(!overrideNames) std::cout << cmd << "\n";
    }
    std::cout.flush();
    int numBots=(int)botCommands.size();
    if(numBots>1 && nplayers!=1){
        std::cout << "\nOnly single-player mode enables specified n-player maps.  When entering multiple bots, please do not try to specify n.\n\n";
        return 1;
    }
    int effectivePlayers = (numBots==1? nplayers : numBots);
    if(effectivePlayers<1 || effectivePlayers>6){
        std::cout << "\nA map can only accommodate between 1 and 6 players.\n\n";
        return 1;
    }
    // Seed / dimensions defaults
    if(seed==0){
        auto now=std::chrono::system_clock::now();
        auto us=std::chrono::duration_cast<std::chrono::microseconds>(now.time_since_epoch()).count();
        seed=(unsigned int)us;
        if(seed==0) seed=1;
    }
    int reqW,reqH;
    if(dimensionsSet){ reqW=dimensions.width; reqH=dimensions.height; }
    else {
        std::mt19937 dimRng((unsigned int)std::time(nullptr));
        int sz=(int)(dimRng()%6u+5u)*5; reqW=sz; reqH=sz;
    }
    g_timestamp=(long long)std::time(nullptr);
    // Generate map
    MapGenerator gen(seed,reqW,reqH,effectivePlayers);
    GameMapData md=gen.generate();
    int W=md.width,H=md.height;
    // If single bot but effectivePlayers>1, only place player 1: clear other owners to neutral (strength unchanged)
    if(numBots==1 && effectivePlayers>1){
        for(int y=0;y<H;y++)for(int x=0;x<W;x++) if(md.initial.cells[(size_t)y][(size_t)x].owner>1) md.initial.cells[(size_t)y][(size_t)x].owner=0;
    }
    // If effectivePlayers == numBots (normal multiplayer/single), owners are 1..numBots as generated.
    std::cout << W << " " << H << "\n";
    std::cout.flush();
    // Replay path
    std::string replayDir=replayDirectory;
    if(replayDir.empty() || replayDir.back()!='/') replayDir.push_back('/');
    std::string replayPath = replayDir + std::to_string(g_timestamp) + "-" + std::to_string(seed) + ".hlt";
    if(quiet && !noReplay){
        std::cout << replayPath << " " << seed << "\n";
        std::cout.flush();
    }
    // Bots
    std::vector<BotProcess> bots((size_t)numBots);
    for(int i=0;i<numBots;i++){ bots[(size_t)i].id=i+1; bots[(size_t)i].command=botCommands[(size_t)i]; }
    std::vector<PlayerStats> stats((size_t)numBots);
    for(int i=0;i<numBots;i++){ stats[(size_t)i].id=i+1; stats[(size_t)i].lastFrameAlive=-1; }
    std::vector<std::string> playerNames((size_t)numBots);
    std::vector<Frame> frames; frames.push_back(md.initial);
    std::vector<std::vector<std::vector<unsigned char>>> allMoves;
    // Launch bots
    for(auto &b: bots) launchBot(b);
    // Init (threads per bot)
    {
        std::vector<std::thread> th;
        std::vector<ReadResult> initResults((size_t)numBots);
        std::vector<char> initDone((size_t)numBots,0);
        for(int i=0;i<numBots;i++){
            th.emplace_back([&,i](){
                BotProcess &b=bots[(size_t)i];
                b.log += " --- Init ---\n";
                std::string msg=serializeInit(b.id,md);
                writeAllFd(b.toFd,msg);
                if(!quiet){ std::lock_guard<std::mutex> lk(coutMutex); std::cout << "Init Message sent to player " << b.id << ".\n"; std::cout.flush(); }
                ReadResult rr=readLineTimeoutByte(b.fromFd,30000,ignoreTimeouts);
                initResults[(size_t)i]=rr;
                if(rr.error){
                    b.errored=true; stats[(size_t)i].errored=true;
                    b.name="Bot #"+std::to_string(b.id)+"; timed out during Init";
                    b.log += "\nERRORED!\n";
                    b.log += rr.response.empty()? "No response received." : ("Response received (if any):\n"+rr.response);
                    writeLogFile(b);
                    killBotProcess(b,false);
                    if(!quiet){ std::lock_guard<std::mutex> lk(coutMutex); std::cout << "Bot #" << b.id << " timeout or error (Unix) 0\n"; }
                } else {
                    b.name=rr.response.substr(0,30);
                    b.log += rr.response + "\n";
                    b.log += " --- Bot used " + std::to_string(rr.elapsedMs) + " milliseconds ---\n";
                    b.log += LOG_SEPARATOR + "\n";
                    if(!quiet){ std::lock_guard<std::mutex> lk(coutMutex); std::cout << "Init Message received from player " << b.id << ", " << b.name << ".\n"; }
                }
                initDone[(size_t)i]=1;
            });
        }
        for(auto &t: th) t.join();
        for(int i=0;i<numBots;i++){
            if(overrideNames) playerNames[(size_t)i]=overrideNameList[(size_t)i].substr(0,30);
            else playerNames[(size_t)i]=bots[(size_t)i].name;
        }
    }
    // Stats for frame0 for non-errored players
    for(int i=0;i<numBots;i++){
        if(!bots[(size_t)i].errored){
            int terr=countTerritory(frames.back(),i+1,W,H);
            if(terr>0){ stats[(size_t)i].lastFrameAlive=0; stats[(size_t)i].territoryAtLast=terr; }
        }
    }
    int maxTurns=(int)(std::sqrt((double)W*(double)H)*10.0);
    auto aliveBotCount = [&](){
        int c=0; for(int i=0;i<numBots;i++) if(!bots[(size_t)i].errored && countTerritory(frames.back(),i+1,W,H)>0)c++; return c;
    };
    bool gameOver=false;
    if(numBots>1 && aliveBotCount()<=1) gameOver=true;
    int turn=0;
    while(!gameOver && turn<maxTurns){
        turn++;
        if(!quiet) std::cout << "Turn " << turn << "\n";
        Frame cur=frames.back();
        struct RespInfo{ bool has=false; bool timeout=false; std::string response; };
        std::vector<RespInfo> resps((size_t)numBots);
        std::vector<std::thread> th;
        std::string mapStr=serializeMap(cur,W,H);
        for(int i=0;i<numBots;i++){
            if(bots[(size_t)i].errored) continue;
            if(countTerritory(cur,i+1,W,H)<=0) continue;
            th.emplace_back([&,i](){
                BotProcess &b=bots[(size_t)i];
                b.log += " --- Frame #" + std::to_string(turn) + " ---\n";
                writeAllFd(b.toFd,mapStr);
                ReadResult rr=readLineTimeoutByte(b.fromFd,1500,ignoreTimeouts);
                if(rr.error){
                    resps[(size_t)i]={true,true,rr.response};
                    b.errored=true; stats[(size_t)i].errored=true;
                    b.log += "\nERRORED!\n";
                    b.log += rr.response.empty()? "No response received." : ("Response received (if any):\n"+rr.response);
                    writeLogFile(b);
                    killBotProcess(b,false);
                } else {
                    resps[(size_t)i]={true,false,rr.response};
                    b.log += rr.response + "\n";
                    b.log += " --- Bot used " + std::to_string(rr.elapsedMs) + " milliseconds ---\n";
                }
            });
        }
        for(auto &t: th) t.join();
        // Invalid character processing in ID order
        std::vector<int> invalidIds;
        for(int i=0;i<numBots;i++){
            if(!resps[(size_t)i].has || resps[(size_t)i].timeout) continue;
            const std::string &resp=resps[(size_t)i].response;
            bool bad=false; for(unsigned char c: resp){ if(!((c>='0'&&c<='9')||c==' ')){bad=true;break;} }
            if(bad){
                invalidIds.push_back(i+1);
                if(!quiet) std::cout << "Bot sent an invalid character - ejecting from game.\n";
                BotProcess &b=bots[(size_t)i];
                b.errored=true; stats[(size_t)i].errored=true;
                b.log += "ERRORED!\nResponse received (if any):\n";
                b.log += resp;
                killBotProcess(b,true);
                writeLogFile(b);
                resps[(size_t)i].response.clear();
            } else {
                // validated: append separator to log
                bots[(size_t)i].log += LOG_SEPARATOR + "\n";
            }
        }
        // Timeout messages in ID order
        if(!quiet){
            for(int i=0;i<numBots;i++) if(resps[(size_t)i].has && resps[(size_t)i].timeout){
                std::cout << "Bot #" << (i+1) << " timeout or error (Unix) 0\n";
            }
        }
        // Convert errored players in cur copy to neutral
        Frame work=cur;
        for(int i=0;i<numBots;i++) if(bots[(size_t)i].errored){
            for(int y=0;y<H;y++)for(int x=0;x<W;x++) if(work.cells[(size_t)y][(size_t)x].owner==(unsigned char)(i+1)) work.cells[(size_t)y][(size_t)x].owner=0;
        }
        // Build moves
        std::vector<std::vector<unsigned char>> moves((size_t)H, std::vector<unsigned char>((size_t)W,0));
        for(int i=0;i<numBots;i++){
            if(!resps[(size_t)i].has || resps[(size_t)i].timeout || bots[(size_t)i].errored) continue;
            const std::string &resp=resps[(size_t)i].response;
            std::vector<long long> nums; long long curNum=0; bool in=false;
            for(size_t k=0;k<=resp.size();k++){
                if(k<resp.size() && resp[k]>='0'&&resp[k]<='9'){ curNum=curNum*10+(resp[k]-'0'); in=true; }
                else { if(in){nums.push_back(curNum);curNum=0;in=false;} }
            }
            for(size_t k=0;k+2<nums.size();k+=3){
                long long x=nums[k],y=nums[k+1],d=nums[k+2];
                if(x>=0&&x<W&&y>=0&&y<H){
                    if(work.cells[(size_t)y][(size_t)x].owner==(unsigned char)(i+1)){
                        moves[(size_t)y][(size_t)x]=(unsigned char)(d%256);
                    }
                }
            }
        }
        allMoves.push_back(moves);
        Frame nxt=processTurn(work,moves,md.productions,W,H);
        frames.push_back(nxt);
        int frameIdx=(int)frames.size()-1;
        for(int i=0;i<numBots;i++){
            int terr=countTerritory(frames.back(),i+1,W,H);
            if(terr>0){ stats[(size_t)i].lastFrameAlive=frameIdx; stats[(size_t)i].territoryAtLast=terr; }
        }
        if(numBots>1 && aliveBotCount()<=1) gameOver=true;
    }
    // Kill remaining bots
    for(auto &b: bots){ if(b.launched && !b.errored) killBotProcess(b,false); }
    // Rankings
    std::vector<int> finalStrength((size_t)numBots,0);
    std::vector<int> finalTerritory((size_t)numBots,0);
    for(int i=0;i<numBots;i++){ finalTerritory[(size_t)i]=countTerritory(frames.back(),i+1,W,H); finalStrength[(size_t)i]=totalStrength(frames.back(),i+1,W,H); }
    std::vector<int> order;
    for(int i=0;i<numBots;i++) order.push_back(i);
    std::sort(order.begin(),order.end(),[&](int a,int b){
        if(stats[(size_t)a].lastFrameAlive!=stats[(size_t)b].lastFrameAlive) return stats[(size_t)a].lastFrameAlive>stats[(size_t)b].lastFrameAlive;
        if(stats[(size_t)a].territoryAtLast!=stats[(size_t)b].territoryAtLast) return stats[(size_t)a].territoryAtLast>stats[(size_t)b].territoryAtLast;
        int sa = (finalTerritory[(size_t)a]>0? finalStrength[(size_t)a]:0);
        int sb = (finalTerritory[(size_t)b]>0? finalStrength[(size_t)b]:0);
        if(sa!=sb) return sa>sb;
        return a>b;
    });
    for(size_t idx=0;idx<order.size();idx++) stats[(size_t)order[idx]].rank=(int)idx+1;
    // Replay output
    if(!noReplay){
        if(!quiet){
            std::cout << "Map seed was " << seed << "\n";
            std::cout << "Opening a file at " << replayPath << "\n";
        }
        std::string json;
        json += "{\"frames\":[";
        for(size_t i=0;i<frames.size();i++){ if(i)json.push_back(','); json+=frameToJson(frames[i],W,H); }
        json += "],\"height\":"+std::to_string(H);
        json += ",\"moves\":[";
        for(size_t i=0;i<allMoves.size();i++){ if(i)json.push_back(','); json+=movesToJson(allMoves[i],W,H); }
        json += "],\"num_frames\":"+std::to_string(frames.size());
        json += ",\"num_players\":"+std::to_string(numBots);
        json += ",\"player_names\":[";
        for(int i=0;i<numBots;i++){ if(i)json.push_back(','); json.push_back('"'); json+=jsonEscape(playerNames[(size_t)i]); json.push_back('"'); }
        json += "],\"productions\":"+prodToJson(md.productions,W,H);
        json += ",\"version\":11,\"width\":"+std::to_string(W)+"}";
        std::ofstream out(replayPath);
        if(!out) throw std::runtime_error("Could not open file for replay");
        out << json;
    }
    if(!quiet){
        for(int i=0;i<numBots;i++){
            std::cout << "Player #" << (i+1) << ", " << playerNames[(size_t)i] << ", came in rank #" << stats[(size_t)i].rank << " and was last alive on frame #" << stats[(size_t)i].lastFrameAlive << "!\n";
        }
    } else {
        for(int i=0;i<numBots;i++){
            std::cout << (i+1) << " " << stats[(size_t)i].rank << " " << stats[(size_t)i].lastFrameAlive << "\n";
        }
        bool anyErr=false;
        for(int i=0;i<numBots;i++) if(stats[(size_t)i].errored){ std::cout << (i+1) << " "; anyErr=true; }
        if(!anyErr) std::cout << " ";
        std::cout << "\n";
        bool anyLog=false;
        for(int i=0;i<numBots;i++) if(bots[(size_t)i].logWritten){ std::cout << logFileNameFor(i+1) << " "; anyLog=true; }
        if(!anyLog) std::cout << " ";
    }
    return 0;
}
