static std::string jsonEscape(const std::string &s) {
    std::string out;
    for (unsigned char c: s) {
        switch(c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\b': out += "\\b"; break;
            case '\f': out += "\\f"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if (c < 0x20) {
                    char buf[8]; snprintf(buf,sizeof(buf),"\\u%04x",c); out += buf;
