    d=(fp,fs,raws);pickle.dump(d,open(cache,'wb'));return d
def wd(d2):return {0:1,1:.2,2:.02,4:.01}.get(d2,0)
def blur(Z,w,h):
    B=[]
    for y in range(h):
      for x in range(w):
        tot=0
        for dy in range(-2,3):
          for dx in range(-2,3):
            weight=wd(dx*dx+dy*dy)
            if weight:tot+=weight*Z[((y+dy)%h)*w+((x+dx)%w)]
        B.append(tot)
    return B

def evaluate(w,h,func):
    paths,L=build_paths(w,h);fp,fs,raws=dataset_any(w,h,list(range(1,61)));sstart=4+2*(L+1);err=0;ex=0;cnt=0
    if w==1 and h==1:return None
    for finals,start in [(fp,4),(fs,sstart)]:
      for j,f in enumerate(finals):
        U=[raws[j][start+2*i]/4294967296 for i in range(L)];Z=[]
        for y in range(h):
          for x in range(w):
            vals=[U[i] for i in paths[y][x]];Z.append(func(vals))
        B=blur(Z,w,h);mx=max(B);M=max(f)
        for v,ff in zip(B,f):
            pred=int(math.floor(v/mx*M+.5));err+=(pred-ff)**2;ex+=pred==ff;cnt+=1
    return err/cnt,ex/cnt
