import sys,math,subprocess,pickle,os
sys.path.insert(0,'/tmp')
from getfast import get,parse
exec(open('/tmp/fit_tree.py').read().split('def dataset')[0])

def dataset_any(w,h,seeds):
    cache=f'/tmp/anydata_{w}x{h}.pkl'
    if os.path.exists(cache):return pickle.load(open(cache,'rb'))
    fp=[];fs=[];raws=[]
    for seed in seeds:
        r,caps=get(w,h,seed,1);pid,wh,p,o,s=parse(caps[0]);fp.append(p);fs.append(s);raws.append(list(map(int,subprocess.check_output(['/tmp/mtseq',str(seed),'5000']).split())))
    d=(fp,fs,raws);pickle.dump(d,open(cache,'wb'));return d
def wd(d2):return {0:1,1:.2,2:.02,4:.01}.get(d2,0)
def blur(Z,w,h):
    B=[]
    for y in range(h):
      for x in range(w):
        tot=0
        for dy in range(-2,3):
          for dx in range(-2,3):
            weight=wd(dx*dx+dy*dy)
            if weight:tot+=weight*Z[((y+dy)%h)*w+((x+dx)%w)]
        B.append(tot)
    return B

