    paths,L=build_paths(w,h);fp,fs,raws=dataset_any(w,h,list(range(1,61)));sstart=4+2*(L+1);err=0;ex=0;cnt=0
    if w==1 and h==1:return None
    for finals,start in [(fp,4),(fs,sstart)]:
      for j,f in enumerate(finals):
        U=[raws[j][start+2*i]/4294967296 for i in range(L)];Z=[]
