 'leaf^1.5':lambda v:v[-1]**1.5,
 'geomean^1.5':lambda v:(math.prod(v)**(1/len(v)))**1.5,
 'max^1.5':lambda v:max(v)**1.5,
 'min^1.5':lambda v:min(v)**1.5,
 'mean':lambda v:sum(v)/len(v),
 'mean^2':lambda v:(sum(v)/len(v))**2,
 'mean^3':lambda v:(sum(v)/len(v))**3,
}
for sz in [(1,8),(8,8),(1,5),(5,5),(1,16),(10,10)]:
    print('SZ',sz)
    for name,f in models.items():print(name,evaluate(sz[0],sz[1],f),flush=True)
