import pickle,math,random,sys
sys.path.insert(0,'/tmp')
exec(open('/tmp/fit_tree.py').read().split('def dataset')[0])
paths,L=build_paths(8,8);fp,fs,raws=pickle.load(open('/tmp/treedata_8x8.pkl','rb'));sstart=4+2*(L+1)
# Precompute Z for prod gamma=1 and gamma=1.5
def getZ(gamma):
    allz=[]
    for finals,start in [(fp,4),(fs,sstart)]:
      for j,f in enumerate(finals):
        U=[raws[j][start+2*i]/4294967296 for i in range(L)];Z=[]
        for y in range(8):
          for x in range(8):
            vals=[U[i] for i in paths[y][x]];Z.append(math.prod(vals)**gamma)
        allz.append((Z,f))
    return allz
def score(allz,weights,R):
    err=0;ex=0;cnt=0
    for Z,f in allz:
        B=[]
        for y in range(8):
          for x in range(8):
            tot=0
            for dy in range(-R,R+1):
              for dx in range(-R,R+1):
                w=weights.get(dx*dx+dy*dy,0)
                if w:tot+=w*Z[((y+dy)%8)*8+((x+dx)%8)]
            B.append(tot)
        mx=max(B);M=max(f)
        for v,ff in zip(B,f):
            pred=int(math.floor(v/mx*M+.5));err+=(pred-ff)**2;ex+=pred==ff;cnt+=1
    return err/cnt,ex/cnt
for gamma in [1,1.25,1.5]:
    allz=getZ(gamma);base={0:1,1:.2,2:.02,4:.01};print('gamma',gamma,'baseR2',score(allz,base,2),flush=True)
    # optimize weights for s values up to 32 (R4)
    svals=[0,1,2,4,5,8,9,10,16,17,20,25,32]
    w={s:base.get(s,0.0) for s in svals};best=score(allz,w,4);rng=random.Random(1)
    for it in range(2000):
        cand=dict(w);s=rng.choice(svals[1:]);cand[s]=max(0,cand[s]+rng.gauss(0,.01));sc=score(allz,cand,4)
        if sc[0]<best[0]:w,best=cand,sc
    print(' opt',best,w,flush=True)
