def eval_blockscale(w,h,mode):
    paths,L=build_paths(w,h);fp,fs,raws=dataset_any(w,h,list(range(1,61)));sstart=4+2*(L+1);err=0;ex=0;cnt=0
    # top-level blocks: group cells by path[0], in order of appearance row-major
    block_ids={};blocks=[]
    for y in range(h):
      for x in range(w):
        top=paths[y][x][0]
        if top not in block_ids:block_ids[top]=len(blocks);blocks.append([])
        blocks[block_ids[top]].append((x,y))
    # arrange blocks in grid by min x/y
    block_pos=[(min(x for x,y in b),min(y for x,y in b)) for b in blocks]
    xs=sorted(set(p[0] for p in block_pos));ys=sorted(set(p[1] for p in block_pos))
    bx={v:i for i,v in enumerate(xs)};by={v:i for i,v in enumerate(ys)};BW=len(xs);BH=len(ys)
    block_grid_index={}; 
    for bi,pos in enumerate(block_pos):block_grid_index[(bx[pos[0]],by[pos[1]])]=bi
    for finals,start in [(fp,4),(fs,sstart)]:
      for j,f in enumerate(finals):
        U=[raws[j][start+2*i]/4294967296 for i in range(L)]
        # coarse grid values (transformed ^1.5), for singleton blocks coarse=leaf same latent; treat as 1? For mode, use latent top as coarse for all blocks, but for singleton it would double-count leaf. We'll set coarse for singleton blocks to 1.0 in product modes, and to its leaf^1.5 in sum modes? Keep: if block has 1 cell, coarse factor=1 for product, =leaf^1.5 for sum (handled below)
        Cgrid=[[0.0]*BW for _ in range(BH)]
        for bi,b in enumerate(blocks):
            top=list(block_ids.keys())[bi] if False else None
        # build mapping top latent -> bi
        top_by_bi=[]
        for b in blocks:
            x,y=b[0];top_by_bi.append(paths[y][x][0])
        for bi in range(len(blocks)):
            gx,gy=bx[block_pos[bi][0]],by[block_pos[bi][1]];Cgrid[gy][gx]=U[top_by_bi[bi]]**1.5
        # smooth Cgrid with 2D kernel (toroidal over blocks)
        Cs=[[0.0]*BW for _ in range(BH)]
        for y in range(BH):
          for x in range(BW):
            tot=0
            for dy in range(-2,3):
              for dx in range(-2,3):
                weight={0:1,1:.2,2:.02,4:.01}.get(dx*dx+dy*dy,0);tot+=weight*Cgrid[(y+dy)%BH][(x+dx)%BW]
            Cs[y][x]=tot
        Z=[]
        for y in range(h):
          for x in range(w):
            path=paths[y][x];leaf=U[path[-1]]
            # block index
            top=path[0];bi=top_by_bi.index(top);gx,gy=bx[block_pos[bi][0]],by[block_pos[bi][1]];cs=Cs[gy][gx]
            if len(path)==1:
                z=leaf**1.5
            elif mode=='prod_smoothblock':z=(leaf**1.5)*cs
            elif mode=='sum_smoothblock':z=(leaf**1.5)+cs
            elif mode=='mean_smoothblock':z=((leaf + (cs**(2/3)))/2)**1.5  # cs is smoothed ^1.5 values; convert back approx
            Z.append(z)
        B=blur(Z,w,h);mx=max(B);M=max(f)
        for v,ff in zip(B,f):
            pred=int(math.floor(v/mx*M+.5));err+=(pred-ff)**2;ex+=pred==ff;cnt+=1
    return err/cnt,ex/cnt
for sz in [(1,8),(8,8),(1,16),(10,10)]:
    print('sz',sz)
