N=8
# Precompute DFT matrices: F[k][x]=exp(-2pi i k x/N)
F=[[cmath.exp(-2j*math.pi*k*x/N) for x in range(N)] for k in range(N)]
def dft2(a):
    # a flat 64
    tmp=[[0j]*N for _ in range(N)]
    for y in range(N):
      for kx in range(N):tmp[y][kx]=sum(a[y*N+x]*F[kx][x] for x in range(N))
    out=[[0j]*N for _ in range(N)]
    for ky in range(N):
      for kx in range(N):out[ky][kx]=sum(tmp[y][kx]*F[ky][y] for y in range(N))
    return out
def idft2(A):
    # inverse using conjugate
    tmp=[[0j]*N for _ in range(N)]
    for y in range(N):
      for kx in range(N):tmp[y][kx]=sum(A[y][k]*F[k][kx].conjugate() for k in range(N))/N
    out=[[0j]*N for _ in range(N)]
    for ky in range(N):
      for kx in range(N):out[ky][kx]=sum(tmp[k][kx]*F[k][ky].conjugate() for k in range(N))/N
    return out
num=[[0j]*N for _ in range(N)];den=[[0.0]*N for _ in range(N)]
for finals,start in [(fp,4),(fs,sstart)]:
  for j,f in enumerate(finals):
    U=[raws[j][start+2*i]/4294967296 for i in range(L)];Z=[]
    for y in range(8):
      for x in range(8):Z.append(math.prod(U[i] for i in paths[y][x])**1.5)
    B=[v/max(f) for v in f]
    ZB=dft2(Z);BB=dft2(B)
    for ky in range(N):
      for kx in range(N):
        num[ky][kx]+=BB[ky][kx]*ZB[ky][kx].conjugate();den[ky][kx]+=abs(ZB[ky][kx])**2
Khat=[[num[ky][kx]/den[ky][kx] if den[ky][kx] else 0j for kx in range(N)] for ky in range(N)]
K=idft2(Khat)
print('kernel impulse response (real, rows dy=0..7 where 5,6,7 are -3,-2,-1):')
for y in range(N):print([round(K[y][x].real,4) for x in range(N)])
print('max imag',max(abs(K[y][x].imag) for y in range(N) for x in range(N)))
print('Khat magnitudes')
for y in range(N):print([round(abs(Khat[y][x]),3) for x in range(N)])
